insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('aa70a83a-9598-4b37-9094-ba54753cdd0d', 'be302e20-d83f-446c-b1d2-a94d543e68d6', $$kromme K: x(t) = cos³(t), y(t) = sin³(t), helling −sin(t)/cos(t) (met figuur)$$,
   $$wiskunde-b-vwo-2021-ii-kromme-k-context1.png$$,
   $$De kromme K is gegeven door de bewegingsvergelijkingen:
x(t) = cos³(t)
y(t) = sin³(t)
met 0 < t < ½π
In de figuur is kromme K getekend. Ook is voor een waarde van t in het bijbehorende punt van K de raaklijn aan K getekend.
De helling in het punt (x(t), y(t)) van K kan worden berekend met: −sin(t)/cos(t)
figuur: kromme K met een raaklijn die de assen snijdt in A en B$$, 'inline'),
  ('5bf9109b-be42-4020-b122-83bbfc3466a4', 'be302e20-d83f-446c-b1d2-a94d543e68d6', $$vergelijking van de raaklijn y = −(sin(t)/cos(t))·x + sin(t)$$,
   $$wiskunde-b-vwo-2021-ii-kromme-k-context2.png$$,
   $$Een vergelijking van de raaklijn in het punt (x(t), y(t)) van K is:
y = −(sin(t)/cos(t))·x + sin(t)$$, 'inline'),
  ('de70b2de-9d33-4b9b-88a4-62a5d7408116', 'be302e20-d83f-446c-b1d2-a94d543e68d6', $$raaklijn snijdt de x-as in A en de y-as in B$$,
   $$wiskunde-b-vwo-2021-ii-kromme-k-context3.png$$,
   $$De raaklijn snijdt de x-as in punt A en de y-as in punt B.$$, 'inline'),
  ('1f24354a-c02c-4b0f-8ed8-f05568a4cf83', 'ab145880-a092-4b50-a2b7-aaf8f2e61495', $$spiegelen van een vector in een lijn$$,
   $$wiskunde-b-vwo-2021-ii-vectoren-spiegelen-context1.png$$,
   $$Wanneer een vector in een lijn wordt gespiegeld, wordt zowel het beginpunt als het eindpunt van de vector in die lijn gespiegeld. Het resultaat is een nieuwe vector die het gespiegelde beginpunt en het gespiegelde eindpunt verbindt.$$, 'inline'),
  ('cb6c486c-7435-48a7-8fc1-70dc85819214', 'ab145880-a092-4b50-a2b7-aaf8f2e61495', $$voorbeeld: AB⃗ gespiegeld in x = 3 geeft CD⃗ (figuur 1)$$,
   $$wiskunde-b-vwo-2021-ii-vectoren-spiegelen-context2.png$$,
   $$figuur 1: vector AB⃗ en zijn spiegelbeeld CD⃗ in de lijn x = 3
In figuur 1 is een voorbeeld weergegeven. Daarin wordt vector AB⃗, met A(1,1) en B(2,3), gespiegeld in de lijn met vergelijking x = 3. Het spiegelbeeld is dan vector CD⃗, met C(5,1) en D(4,3)$$, 'inline'),
  ('eb398017-7e20-4372-88b3-82249a41c973', 'ab145880-a092-4b50-a2b7-aaf8f2e61495', $$punt F(7,2) en vector OF⃗$$,
   $$wiskunde-b-vwo-2021-ii-vectoren-spiegelen-context3.png$$,
   $$Gegeven is punt F(7,2) en vector OF⃗.$$, 'inline'),
  ('273761f9-02da-42bb-8749-b8dd9f086410', 'ab145880-a092-4b50-a2b7-aaf8f2e61495', $$OG⃗ is het spiegelbeeld van OF⃗ in de x-as, p·OF⃗ + q·OG⃗ = (7, −3)$$,
   $$wiskunde-b-vwo-2021-ii-vectoren-spiegelen-context4.png$$,
   $$Vector OF⃗ wordt in de x-as gespiegeld. Het spiegelbeeld is vector OG⃗. Voor één bepaalde combinatie van p en q geldt p·OF⃗ + q·OG⃗ = (7, −3).$$, 'inline'),
  ('c55ce693-aaa1-4212-8c7d-325f6a3872d5', 'ab145880-a092-4b50-a2b7-aaf8f2e61495', $$lijn k met vectorvoorstelling (x, y) = t·(3, 4)$$,
   $$wiskunde-b-vwo-2021-ii-vectoren-spiegelen-context5.png$$,
   $$Ook is gegeven de lijn k met vectorvoorstelling (x, y) = t·(3, 4).
Zie figuur 2$$, 'inline'),
  ('389f5376-911c-4f4a-b068-35ade2ca5437', 'ab145880-a092-4b50-a2b7-aaf8f2e61495', $$OF⃗ wordt gespiegeld in lijn k$$,
   $$wiskunde-b-vwo-2021-ii-vectoren-spiegelen-context6.png$$,
   $$Vector OF⃗ wordt gespiegeld in lijn k.$$, 'inline'),
  ('9026a391-cf55-4180-96e9-eb783d3af432', 'ab145880-a092-4b50-a2b7-aaf8f2e61495', $$lijn k en punt F (figuur 2)$$,
   $$wiskunde-b-vwo-2021-ii-vectoren-spiegelen-context7.png$$,
   $$figuur 2: de lijn k en de vector OF⃗$$, 'inline'),
  ('81477acb-3e98-473f-9293-00db0b3258a2', 'a548fb18-93cd-43b1-8286-2e88f209c55f', $$functie fₚ(x) = ¼x⁴ − x³ + px, raaklijnen k en l, punten A, B en M (met figuur 1)$$,
   $$wiskunde-b-vwo-2021-ii-raaklijnen-bij-een-vierdegraadsfunctie-context1.png$$,
   $$De functie fₚ is gegeven door:
fₚ(x) = ¼x⁴ − x³ + px
De lijn k heeft vergelijking y = px. Lijn k raakt de grafiek van fₚ voor iedere waarde van p in de oorsprong.
De lijn l is de raaklijn aan de grafiek van fₚ in het punt A met x-coördinaat 2.
Lijn l snijdt de y-as voor elke waarde van p in het punt B(0,4).
Punt M is het snijpunt van lijn k en lijn l.
In figuur 1 is de grafiek van fₚ weergegeven voor een waarde van p. De raaklijnen k en l zijn gestippeld weergegeven.
figuur 1: grafiek van fₚ met de raaklijnen k en l en de punten A, B en M$$, 'inline'),
  ('6f9f32e6-d2ae-4473-a024-754fa8b6ca38', 'a548fb18-93cd-43b1-8286-2e88f209c55f', $$vlakdeel V ingesloten door lijn k en de grafiek van fₚ (met figuur 2)$$,
   $$wiskunde-b-vwo-2021-ii-raaklijnen-bij-een-vierdegraadsfunctie-context2.png$$,
   $$De lijn k en de grafiek van fₚ sluiten een vlakdeel V in. In figuur 2 is voor een waarde van p vlakdeel V grijs weergegeven
figuur 2: grafiek van fₚ met de lijn k en het grijze vlakdeel V$$, 'inline'),
  ('b67b9e06-2bd8-4513-a8cb-8aa18e71d21b', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$exponentiële groei van een spaarbedrag en verdubbelingstijd$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context1.png$$,
   $$Op een spaarrekening wordt een bedrag gestort. Het jaarlijkse rentepercentage op deze spaarrekening is constant. Hierdoor groeit het bedrag op de spaarrekening exponentieel. Voor de spaarder is het interessant om te weten na hoeveel jaar het bedrag is verdubbeld.$$, 'inline'),
  ('3f3e6a73-b1c9-4b40-96e9-24cb86e4cb1a', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$formule T = ln(2)/ln(1 + p/100)$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context2.png$$,
   $$De verdubbelingstijd is exact te berekenen met de formule T = ln(2)/ln(1 + p/100).
Hierin is T de verdubbelingstijd in jaren en p het jaarlijkse rentepercentage.$$, 'inline'),
  ('9aeee1fa-25b5-4211-95a7-844666e0e561', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$bankenformules en de functie N(x) = ln(1 + x/100)$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context3.png$$,
   $$Als je geen rekenmachine gebruikt, is de formule voor T onhandig. Daarom gebruiken bankmedewerkers, als zij de verdubbelingstijd willen weten, formules die de exacte verdubbelingstijd benaderen. Zulke formules noemen we bankenformules. Om zo''n bankenformule te vinden onderzoeken we eerst de noemer van de formule voor T. We bekijken dus de functie N gegeven door:
N(x) = ln(1 + x/100) (met x ≥ 0)
In de figuur is de grafiek van N getekend. Ook is de raaklijn k aan de grafiek van N in O getekend.$$, 'inline'),
  ('6f2febdf-08d4-427c-8837-eb139aac0ce4', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$grafiek van N met raaklijn k in O (figuur)$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context4.png$$,
   $$figuur: grafiek van N met de raaklijn k in O$$, 'inline'),
  ('efecee7e-6708-4eda-b229-6f49e8dfac42', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$raaklijn k: y = x/100, verticale afstand tussen N en k$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context5.png$$,
   $$Een vergelijking van k is y = (1/100)x. Als x > 0 ligt de grafiek van N onder lijn k.
Verder geldt: als x groter wordt, dan wordt de verticale afstand tussen de grafiek van N en lijn k groter.$$, 'inline'),
  ('58c9824e-3f9a-4341-a5b7-7687ede566d8', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$benadering T ≈ 70/p voor kleine p$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context6.png$$,
   $$Voor kleine positieve waarden van x ligt lijn k dicht bij de grafiek van N. Je kunt dus zeggen dat voor kleine positieve waarden van p geldt dat ln(1 + p/100) ongeveer gelijk is aan (1/100)p. Dan geldt dus:
T ≈ ln(2)/((1/100)p) ofwel T ≈ (100·ln(2))/p ≈ 70/p$$, 'inline'),
  ('f1294d68-7596-48b2-913c-20bee740dba2', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$bankenformule T₁ = 70/p$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context7.png$$,
   $$Daarmee is een voorbeeld gevonden van een bankenformule: de exacte verdubbelingstijd T kan voor kleine positieve waarden van p benaderd worden door 70/p te berekenen. Deze benadering noemen we T₁.$$, 'inline'),
  ('9b77e7f3-d9be-4f7e-8eae-82f2c1e9861c', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$bankenformule T₂ = 72/p$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context8.png$$,
   $$De benadering met de formule T₁ = 70/p verschilt voor toenemende waarden van p steeds meer van de waarde volgens de exacte formule, waarmee de benadering dus steeds slechter wordt. Daarom wordt in de praktijk het getal 70 in de teller aangepast als p groter wordt, bijvoorbeeld naar 72. Deze benadering noemen we T₂.$$, 'inline'),
  ('aaa4dfce-1930-4d56-bec2-b5a14f9e89fb', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$vergelijking van T₁ en T₂ met de exacte formule$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context9.png$$,
   $$In de tabel wordt voor twee waarden van p de verdubbelingstijd in jaren volgens de bankenformules T₁ = 70/p en T₂ = 72/p vergeleken met de verdubbelingstijd volgens de exacte formule.$$, 'inline'),
  ('8895359f-8e7f-47fa-8bc5-2a41d9a42152', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$tabel: verdubbelingstijden voor p = 1,5 en p = 5,5$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context10.png$$,
   $$tabel
rentepercentage | p = 1,5 | p = 5,5
exacte formule T = ln(2)/ln(1 + p/100) | 46,56 | 12,95
bankenformule T₁ = 70/p | 46,67 | 12,73
bankenformule T₂ = 72/p | 48,00 | 13,09$$, 'inline'),
  ('775fc0b0-20b3-421f-ae87-f62a0f715c36', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$T₁ beter bij p = 1,5, T₂ beter bij p = 5,5$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context11.png$$,
   $$In de tabel is te zien dat voor p = 1,5 de bankenformule T₁ = 70/p een betere benadering geeft dan de bankenformule T₂ = 72/p. In de tabel is ook te zien dat voor p = 5,5 de benadering met T₂ = 72/p beter is dan met T₁ = 70/p.$$, 'inline'),
  ('fcf65082-73cf-40fd-9c4e-3e464b00a3d8', '7942dbcd-f35f-4039-8bae-354e8301d5b7', $$vanaf een bepaald rentepercentage is T₂ beter dan T₁$$,
   $$wiskunde-b-vwo-2021-ii-bankenformules-context12.png$$,
   $$Vanaf een bepaald rentepercentage p geeft de formule T₂ = 72/p een betere benadering van de exacte verdubbelingstijd dan de formule T₁ = 70/p.$$, 'inline'),
  ('d679de6d-585e-417a-8ace-d368394a8cf9', '1f2ac688-fc52-49fa-bf71-1b4f2e29d7a3', $$functies f(x) = 2√x en g(x) = √(2x), punt P(p, 2√p), lijn OP snijdt g in Q$$,
   $$wiskunde-b-vwo-2021-ii-twee-wortelgrafieken-context1.png$$,
   $$De functies f en g zijn gegeven door f(x) = 2√x en g(x) = √(2x).
Op de grafiek van f ligt het punt P(p, 2√p).
De helling van de grafiek van f in P is gelijk aan 1/√p.
De lijn door O en P snijdt de grafiek van g in het punt Q. Deze situatie is weergegeven in figuur 1.$$, 'inline'),
  ('e5387023-9af6-4331-b7f7-92fc706e3e6e', '1f2ac688-fc52-49fa-bf71-1b4f2e29d7a3', $$grafieken van f en g met P en Q (figuur 1)$$,
   $$wiskunde-b-vwo-2021-ii-twee-wortelgrafieken-context2.png$$,
   $$figuur 1: grafieken van f en g met de lijn door O en P en het punt Q$$, 'inline'),
  ('53fdc537-69df-4567-b3e3-0ebe0f659228', '1f2ac688-fc52-49fa-bf71-1b4f2e29d7a3', $$helling van g in Q is gelijk aan helling van f in P$$,
   $$wiskunde-b-vwo-2021-ii-twee-wortelgrafieken-context3.png$$,
   $$De helling van de grafiek van g in punt Q is voor elke waarde van p gelijk aan de helling van de grafiek van f in punt P.$$, 'inline'),
  ('d2a3217d-f81e-4ac3-9bb1-92244890c68f', '1f2ac688-fc52-49fa-bf71-1b4f2e29d7a3', $$p = 4, punt R op g onder P, raaklijnen snijden in S(−4,0)$$,
   $$wiskunde-b-vwo-2021-ii-twee-wortelgrafieken-context4.png$$,
   $$We kiezen nu p = 4. Punt R ligt op de grafiek van g recht onder punt P. De raaklijnen in P en R snijden elkaar in het punt S(−4,0). Zie figuur 2.$$, 'inline'),
  ('62342c98-2578-42af-94b3-326a363d9797', '1f2ac688-fc52-49fa-bf71-1b4f2e29d7a3', $$grafieken met raaklijnen, driehoek PRS en grijs vlakdeel (figuur 2)$$,
   $$wiskunde-b-vwo-2021-ii-twee-wortelgrafieken-context5.png$$,
   $$figuur 2: grafieken van f en g met de raaklijnen in P en R, het punt S en het grijze vlakdeel$$, 'inline'),
  ('787ab497-4856-45d1-85d4-aacfe576a16f', '1f2ac688-fc52-49fa-bf71-1b4f2e29d7a3', $$vlakdeel ingesloten door PR en de grafieken van f en g$$,
   $$wiskunde-b-vwo-2021-ii-twee-wortelgrafieken-context6.png$$,
   $$Het lijnstuk PR en de grafieken van f en g sluiten een vlakdeel in. Dit vlakdeel is in figuur 2 grijsgemaakt.$$, 'inline'),
  ('62c3fdca-7588-45ff-a1ce-71054a7e9b89', '01ef1824-2bce-4510-80a4-ff112207ac34', $$functie f(x) = e^(−1/x)$$,
   $$wiskunde-b-vwo-2021-ii-asymptoten-en-raaklijnen-context1.png$$,
   $$De functie f is gegeven door f(x) = e^(−1/x).
In figuur 1 is de grafiek van f weergegeven.$$, 'inline'),
  ('fc836594-a282-4049-bf08-4955d1eaaffa', '01ef1824-2bce-4510-80a4-ff112207ac34', $$grafiek van f (figuur 1)$$,
   $$wiskunde-b-vwo-2021-ii-asymptoten-en-raaklijnen-context2.png$$,
   $$figuur 1: grafiek van f$$, 'inline'),
  ('2915b829-4792-4b1a-b953-d05daf6c2c3d', '01ef1824-2bce-4510-80a4-ff112207ac34', $$f en de inverse van f hebben elk twee asymptoten$$,
   $$wiskunde-b-vwo-2021-ii-asymptoten-en-raaklijnen-context3.png$$,
   $$De grafiek van f heeft twee asymptoten. Daarom heeft de grafiek van de inverse functie van f ook twee asymptoten.$$, 'inline'),
  ('64fe7562-336f-467c-8b2e-7ee4bb4d754b', '01ef1824-2bce-4510-80a4-ff112207ac34', $$afgeleide f′(x) = (1/x²)·e^(−1/x), domein x > 0, raaklijn in P snijdt de x-as in S$$,
   $$wiskunde-b-vwo-2021-ii-asymptoten-en-raaklijnen-context4.png$$,
   $$De afgeleide functie van f wordt gegeven door f′(x) = (1/x²)·e^(−1/x).
In de rest van de opgave is het domein van f beperkt tot x > 0.
De raaklijn aan de grafiek van f in een punt P snijdt de x-as in een punt S.
Zie figuur 2.$$, 'inline'),
  ('9405e7b0-1f9f-45f0-8da4-feee373209af', '01ef1824-2bce-4510-80a4-ff112207ac34', $$grafiek van f met de raaklijn in P en het punt S (figuur 2)$$,
   $$wiskunde-b-vwo-2021-ii-asymptoten-en-raaklijnen-context5.png$$,
   $$figuur 2: grafiek van f met de raaklijn in P die de x-as snijdt in S$$, 'inline'),
  ('e7dc786d-ec44-46d4-982b-c2c1b00b3888', '01ef1824-2bce-4510-80a4-ff112207ac34', $$x-coördinaat van S is maximaal voor een positie van P$$,
   $$wiskunde-b-vwo-2021-ii-asymptoten-en-raaklijnen-context6.png$$,
   $$De x-coördinaat van S hangt af van de positie van P op de grafiek van f. Er is een positie van P waarvoor de x-coördinaat van S maximaal is.$$, 'inline'),
  ('14b35ee5-7db9-4b3d-9534-b17d6035dd10', 'd5935a47-e6f5-489c-b779-c8897ee24f94', $$lijn k door O met hoek α, cirkel met middelpunt M en straal 1 raakt k in A (met figuur 1)$$,
   $$wiskunde-b-vwo-2021-ii-driehoek-in-cirkel-context1.png$$,
   $$Een lijn k gaat door de oorsprong O en maakt een hoek α met de positieve x-as, met 0° < α < 90°.
Op de positieve x-as ligt een punt M zo dat de cirkel met middelpunt M en straal 1 lijn k raakt. Punt A is het raakpunt en hoek OAM is dus 90°.
In figuur 1 is de situatie voor een bepaalde waarde van α weergegeven.
figuur 1: lijn k, de cirkel met middelpunt M en het raakpunt A$$, 'inline'),
  ('acae91ce-35d9-4e6c-95eb-3fbced1afeef', 'd5935a47-e6f5-489c-b779-c8897ee24f94', $$coördinaten van A uitgedrukt in α$$,
   $$wiskunde-b-vwo-2021-ii-driehoek-in-cirkel-context2.png$$,
   $$De coördinaten van A(x_A, y_A) kunnen worden uitgedrukt in α$$, 'inline'),
  ('63c6cac9-b9ca-4843-89b9-348b4250f3e5', 'd5935a47-e6f5-489c-b779-c8897ee24f94', $$punt B en punt C op de cirkel, driehoek MBC$$,
   $$wiskunde-b-vwo-2021-ii-driehoek-in-cirkel-context3.png$$,
   $$Voor elke hoek α (met 0° < α < 90°) raakt lijn k de cirkel in punt A. Verder snijdt de cirkel de x-as rechts van het middelpunt in een punt B. Op de cirkel ligt een punt C boven de x-as, zo dat de lijn door M en C hoek AMB middendoor deelt. De positie van M, en dus ook de oppervlakte van driehoek MBC, hangt af van hoek α. In figuur 2 en 3 is voor twee verschillende waarden van α de situatie weergegeven.$$, 'inline'),
  ('a027453c-c324-464c-ae6b-96b67840d44f', 'd5935a47-e6f5-489c-b779-c8897ee24f94', $$situatie voor twee waarden van α (figuur 2 en figuur 3)$$,
   $$wiskunde-b-vwo-2021-ii-driehoek-in-cirkel-context4.png$$,
   $$figuur 2 en figuur 3: de grijze driehoek MBC voor twee waarden van α$$, 'inline'),
